"""Render final argument from checked claims and saved AI actions; no model calls."""
import csv,json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from pipeline import hosted as h
ROOT=h.ROOT
def build():
 ranking=list(csv.DictReader((ROOT/'grading/ranking.csv').open()));claims={r['claim_id']:r for r in csv.DictReader((ROOT/'grading/claims.csv').open())};recs={r['issue_id']:r for r in json.loads((ROOT/'evidence/hosted/partial-memo.json').read_text())['recommendations']};d=h.c.dbopen(h.STATE/'partial.sqlite')
 for row in ranking:
  for metric in ('complaint_count','severity_sum','mean_severity','priority_score'):
   claim=claims[row['issue_id']+'-'+metric];assert claim['value']==row[metric] and claim['issue_id']==row['issue_id']
 for issue,rec in recs.items():
  source=d.execute('SELECT text FROM sources WHERE id=?',(rec['review_id'],)).fetchone();label=d.execute('SELECT result FROM labels WHERE id=? AND config=?',(rec['review_id'],h.LABEL_CONFIG)).fetchone();v=json.loads(label[0]);assert rec['quote'] in source[0] and issue=='issue-'+v['topic'] and v['intent'] in ('complaint','cancellation')
 d.close();p={row['issue_id']:row for row in ranking}
 lines=['# Decision memo — Spotify historical partial cohort','', '**Recommendation: prioritize playback reliability for the next quarter, with a focused usability workstream and a separate billing-risk triage lane.** This advice uses historical reviews, not evidence of Spotify’s current product state. The cohort contains 100,000 classified reviews out of 660,609 nonempty source reviews; all 660,622 source rows were ingested. It is explicitly partial and source-order selected. Counts below are review records, including separate exact-text duplicate source records; they are not unique customers. Scope: `grading/run.json`.','', '## Why playback first','', f"Playback leads the required priority ranking: **{int(p['issue-playback']['complaint_count']):,} complaint/cancellation reviews**, **{int(p['issue-playback']['severity_sum']):,} severity sum**, and mean severity **{p['issue-playback']['mean_severity']}**. Claims: `issue-playback-complaint_count`, `issue-playback-severity_sum`, `issue-playback-mean_severity`. The baseline is a transparent aggregate of ordinal labels, not an estimate of economic harm.",'',recs['issue-playback']['action'],'', '> '+recs['issue-playback']['quote'].replace('\n','\n> '),'', 'Source: `'+recs['issue-playback']['review_id']+'`; issue: `issue-playback`. Treat this as a concrete regression hypothesis, not proof that the cited update caused all playback complaints.','', '## Alternatives and trade-offs','', f"**Usability** has more complaint/cancellation records (**{int(p['issue-usability']['complaint_count']):,}**) but a lower severity sum (**{int(p['issue-usability']['severity_sum']):,}**) and mean (**{p['issue-usability']['mean_severity']}**). Claims: `issue-usability-complaint_count`, `issue-usability-severity_sum`, `issue-usability-mean_severity`. Prioritize a bounded investigation of song-selection/shuffle predictability alongside reliability; do not interpret this ranking as permission to redesign every control.",'',recs['issue-usability']['action'],'', '> '+recs['issue-usability']['quote'].replace('\n','\n> '),'', 'Source: `'+recs['issue-usability']['review_id']+'`; issue: `issue-usability`.','', f"**Billing** is a smaller aggregate lane: **{int(p['issue-billing']['complaint_count']):,} records**, severity sum **{int(p['issue-billing']['severity_sum']):,}**, mean **{p['issue-billing']['mean_severity']}**. Claims: `issue-billing-complaint_count`, `issue-billing-severity_sum`, `issue-billing-mean_severity`. Maintain manual triage for serious payment/privacy reports even when their aggregate rank is lower; this corpus contains no validated account-revenue or confirmed-churn data.",'',recs['issue-billing']['action'],'', '> '+recs['issue-billing']['quote'].replace('\n','\n> '),'', 'Source: `'+recs['issue-billing']['review_id']+'`; issue: `issue-billing`.','', '## Reproducible baseline','', 'Complaint/cancellation records only. Priority equals integer severity sum; descending score, then ascending issue ID breaks ties. Means are six-decimal half-up. The complete `membership.csv`, `ranking.csv` and `claims.csv` are in the grading export.','', '| Rank | Stable issue | Records | Severity sum / priority | Mean severity |','|---:|---|---:|---:|---:|']
 for row in ranking:lines.append(f"| {row['rank']} | {row['issue_id']} | {row['complaint_count']} | {row['severity_sum']} | {row['mean_severity']} |")
 lines += ['', 'Exact table claims by issue:']
 for row in ranking:lines.append('- '+row['issue_id']+': '+', '.join('`'+row['issue_id']+'-'+m+'`' for m in ('complaint_count','severity_sum','priority_score','mean_severity'))+'.')
 sensitivity=json.loads((ROOT/'reports/ranking-sensitivity.json').read_text())['scenarios']
 lines += ['', '## Offline ranking sensitivity — baseline retained','', 'These are separate descriptive stress tests on saved labels, not corrected classifications or alternative grading exports. Original baseline values above remain unchanged. Reproduce with `python3 pipeline/ranking_sensitivity.py`; complete results and input hashes: `reports/ranking-sensitivity.json`.','', '| Scenario | Classified records retained | Playback score (rank) | Usability score (rank) | Playback lead |','|---|---:|---:|---:|---:|']
 for name,label in [('baseline','Required baseline'),('exact_text_once','Each exact original text once'),('exclude_needs_review','Exclude needs_review=true')]:
  s=sensitivity[name];v=s['playback_vs_usability'];lines.append(f"| {label} | {s['retained_classifications']:,} | {v['playback_severity_sum']:,} ({v['playback_rank']}) | {v['usability_severity_sum']:,} ({v['usability_rank']}) | {v['playback_minus_usability']:,} |")
 lines += ['', 'Playback remains first and usability second in both checks. Exact-text deduplication removes 21,008 classified source records and preserves the entire issue order; the playback lead widens from 1,329 to 1,908 severity points. Excluding 11,407 flagged records narrows the lead to 1,139: other falls from fifth to seventh, while downloads rises from sixth to fifth and access from seventh to sixth. This supports the direction of the playback investigation within these two checks, not statistical significance or population robustness. Distinct texts are not distinct customers. Model review flags are not calibrated uncertainty, and excluding flagged records may remove harder cases selectively.','', '## Proposed investigation and success measurements','', 'Investigate startup and first-track playback failures first: reproduce clean launch, app/OS update, background resume and network-change paths; capture structured error codes and trace startup, authentication, track resolution, buffering and decoder initialization. Stratify by device/OS/app version, connectivity and plan, and compare affected paths with unaffected controls. Treat the historical Samsung/update quote as one reproduction lead, not a diagnosis of current failures. Handle shuffle/control complaints as a separate usability workstream.','', '**Proposed measurements; not observed results:** instrument eligible play attempts with a documented attempt ID and timeout. Playback-start failure rate = attempts that error or produce no audible playback by the predefined timeout divided by eligible play attempts. Record exclusions and retries consistently; report successful-start latency alongside failures so slow starts are not hidden. Crash-free listening sessions = eligible listening sessions without a fatal app crash divided by all eligible listening sessions, using a fixed session boundary. Validate crash and playback telemetry completeness, including sessions that never start audio.','', 'Establish a prospective baseline before setting numerical targets. Evaluate a candidate fix against a randomized holdback where feasible, or a documented staged rollout with comparable cohorts; predeclare the observation window, minimum sample and confidence-interval method. Success would mean a lower playback-start failure rate with uncertainty reported, improved crash-free sessions, and no material regression in start latency, rebuffering or battery use. Set acceptable guardrails before rollout. None of these rates, targets, experiments or improvements was measured in this review corpus; no retention, revenue or causal gain is claimed.','', '## Diagnostic error analysis — no retuning','', 'Three existing model–human disagreements were inspected after the production run. Golden-50 expected labels, original model predictions and per-review comparisons are public under `evals/` in the repository and current evidence ZIP, with the owner’s authorization. They remain evaluation evidence only, never model inputs or tuning data; the following summaries describe the error mechanisms. Original agreement remains 74% topic, 80% intent and 66% severity. Human answers are diagnostic annotations, not automatically authoritative when wording conflicts with the shared contract. No labels, prompts or ranking inputs were revised.','', '- **Mixed lyrics and playback/control problems:** the highest supported severity selects the primary problem; if severities tie, choose the first specific problem mentioned. Missing lyrics generally concerns catalog availability, while a blocked core playback task can support a higher severity. Inventing total loss from a restricted control would overstate severity. Such boundary errors can move severity points between catalog and playback and alter their relative priorities.','- **Ad-frequency complaint phrased as a request:** the contract gives a reported negative experience precedence over a desired change. A pure feature request has severity one; a described annoyance or degraded function needs its own supported severity. A request/complaint boundary error can omit a real annoyance from the complaint-only ranking or include a pure wish in it, affecting usability counts.','- **App launch/playback failure with angry or star language:** explicit inability to open the app or play supports blocked-core-task severity; anger or a low rating alone does not. Recovery or a workaround changes the interpretation. The inspected pair illustrates that disagreement can also reflect a human annotation that deserves contract-based review; it is not evidence that every model score should be lowered. Severity errors can expand or narrow the playback–usability gap.','', 'These examples explain plausible mechanisms, not measured corrections to the 100,000 labels. Their frequency and net effect cannot be inferred from a few selected disagreements. Keep a fresh blind set for any future tuning decision.']
 lines += ['', '## Limits and next decision','', 'The cohort is self-selected, historical, partial and not population-representative. Primary topics are coarse and do not establish root causes. Exact duplicates contribute separate records to business counts, so repeated language can concentrate scores. Golden-50 disagreement is substantial; provenance and schema checks do not prove label correctness. Sentiment and review flags lack completed human gold labels, and entities were not extracted. A golden-informed experimental prompt was rejected; the original frozen classifier produced this ranking.','', 'Start with reproducible failure investigations and inspect source evidence before committing a large roadmap. Compare representative device/update paths and control states, and define prospective product measurements before claiming improvement. The reviews alone cannot establish causal retention gains, revenue impact or actual cancellation outcomes.','']
 (ROOT/'MEMO.md').write_text('\n'.join(lines));h.c.dump(ROOT/'reports/memo-validation.json',{'status':'passed','issue_metric_cells_checked':len(ranking)*4,'all_claim_values_match':True,'all_eight_recommendation_ids_quotes_memberships_match':True,'source':'grading/claims.csv and data/hosted/partial.sqlite','memo_scope':'partial, 100000 classifications'});print('Memo written; 32 issue-metric values and all eight saved recommendation citations validated.')
if __name__=='__main__':build()
